using System.Text.Json;
using FamilyVeda.Application.Agents;
using FamilyVeda.Application.Common;
using FamilyVeda.Application.Records;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Records;
using Microsoft.EntityFrameworkCore;

namespace FamilyVeda.Infrastructure.Records;

// The background half of extraction. Access, consent and audit were enforced by ExtractAsync before the report was
// queued; this half only runs the Extraction agent, which reaches data solely through the allow-listed ToolDispatcher.
public sealed partial class LabExtractionService
{
    public async Task RunQueuedAsync(Guid reportId, CancellationToken stoppingToken)
    {
        var report = await dbContext.LabReports.SingleOrDefaultAsync(x => x.Id == reportId, stoppingToken);
        // Already finished, retried or deleted: nothing to do.
        if (report is null || report.OcrStatus != OcrStatus.Processing) return;
        // The read starts now: touch UpdatedAt so the stale window counts from here, not from queueing.
        dbContext.Entry(report).Property(x => x.UpdatedAt).IsModified = true;
        await dbContext.SaveChangesAsync(stoppingToken);

        // The read budget also starts here, when the read starts.
        using var ocrTimeout = new CancellationTokenSource(OcrTimeout);
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(ocrTimeout.Token, stoppingToken);
        try
        {
            var agent = agents.Single(x => x.Kind == AgentKind.Extraction);
            var result = await agent.RunAsync(new AgentRunContext(reportId, report.MemberId, "{}"), linked.Token);
            using var output = JsonDocument.Parse(result.OutputJson);
            _ = output.RootElement.GetProperty("valuesExtracted").GetInt32();
            _ = output.RootElement.GetProperty("flagsExtracted").GetInt32();
            await FinishAsync(report, OcrStatus.Completed, null);
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested && !ocrTimeout.IsCancellationRequested)
        {
            // Host shutting down: leave it Processing so startup recovery queues it again.
            throw;
        }
        catch (OperationCanceledException) when (ocrTimeout.IsCancellationRequested)
        {
            await FinishAsync(report, OcrStatus.Failed, OcrFailureCodes.TimedOut);
        }
        catch (OperationCanceledException)
        {
            await FinishAsync(report, OcrStatus.Failed, OcrFailureCodes.Cancelled);
        }
        catch (ProcessingException exception)
        {
            // Our own codes (page limit, text limit, unreadable file) map to patient-safe copy in each client.
            await FinishAsync(report, OcrStatus.Failed, exception.Code ?? OcrFailureCodes.Failed);
        }
        catch (Exception exception) when (exception is not OutOfMemoryException and not StackOverflowException)
        {
            await FinishAsync(report, OcrStatus.Failed, OcrFailureCodes.Failed);
        }
    }

    private async Task FinishAsync(LabReport report, OcrStatus status, string? errorCode)
    {
        report.OcrStatus = status;
        report.OcrErrorCode = errorCode;
        await dbContext.SaveChangesAsync(CancellationToken.None);
    }
}
